import json
from pathlib import Path
rows=[
('English','Verbal Reasoning','Book is to reading as fork is to _____.',['writing','eating','running','sleeping','drawing'],1,'A book is used for reading. A fork is used for eating.'),
('English','Verbal Reasoning','All engineers in a group study mathematics. Hana is an engineer in that group. What must follow?',['Hana teaches mathematics.','Everyone studying mathematics is an engineer.','Hana studies mathematics.','Hana dislikes mathematics.','No conclusion follows.'],2,'The rule applies to every engineer in the specified group. Hana belongs to that group, so Hana studies mathematics.'),
('English','Grammar','Choose the correct sentence.',['She have finished her work.','She has finish her work.','She has finished her work.','She having finished her work.','She has finishing her work.'],2,'The present perfect uses has with a singular third-person subject and the past participle finished.'),
('English','Grammar','Choose the correct completion: Neither the lecturer nor the students ___ absent.',['is','was','has','are','be'],3,'With neither ... nor, the verb agrees with the nearer subject. Students is plural, so are is correct.'),
('English','Vocabulary','Which word is closest in meaning to meticulous?',['Careless','Hasty','Thorough','Uncertain','Angry'],2,'Meticulous means showing great care and attention to detail. Thorough is the closest choice.'),
('English','Vocabulary','Choose the antonym of abundant.',['Plentiful','Copious','Ample','Numerous','Scarce'],4,'Abundant means present in large quantities. Scarce means insufficient or difficult to find.'),
('English','Reading Comprehension','Passage: The library extended its opening hours during examination week. Attendance increased, but borrowing remained unchanged. Which statement is directly supported?',['More books were borrowed.','The library was closed during exams.','Attendance decreased.','More students visited the library.','Every visitor borrowed a book.'],3,'The passage explicitly says attendance increased. It does not say borrowing increased.'),
('English','Reading Comprehension','Passage: Although solar panels cost money initially, they can reduce electricity expenses over time. What is the main idea?',['Solar panels are always free.','Initial costs may be offset by later savings.','Electricity is unnecessary.','Solar panels never need maintenance.','Every household must buy panels.'],1,'The contrast between initial expense and later reduced electricity costs supports the possibility of savings over time, not guaranteed savings for every household.'),
('Mathematics','Quantitative Problem Solving','A price rises from 200 birr to 250 birr. What is the percentage increase?',['10%','20%','25%','50%','125%'],2,'Increase = 250 - 200 = 50 birr. Percentage increase = (50 / 200) × 100 = 25%.'),
('Mathematics','Quantitative Problem Solving','Solve $3x + 7 = 22$.',['3','4','5','6','7'],2,'Subtract 7 from both sides: 3x = 15. Divide by 3: x = 5. Substitution gives 3(5) + 7 = 22.'),
('Mathematics','Analytical Reasoning','What comes next in the sequence 2, 6, 12, 20, 30, ...?',['36','40','41','42','44'],3,'The differences are 4, 6, 8, 10. Continuing this pattern gives a difference of 12, so the next term is 30 + 12 = 42.'),
('Mathematics','Analytical Reasoning','Three students A, B, C stand in a line. A is before B, and B is before C. Which order is possible?',['A, B, C','A, C, B','B, A, C','B, C, A','C, B, A'],0,'Combining A before B and B before C gives the unique ordering A, B, C.')]
qs=[];chunks=[]
for i,(subject,domain,text,options,answer,explanation) in enumerate(rows,1):
 q=dict(id=f'demo-q-{i}',subject=subject,domain=domain,text=text,options=options,answer=answer,explanation=explanation,source='Havan authored demonstration practice — not an official UAT paper',repository='trained');qs.append(q)
 chunks.append(dict(id=f'demo-c-{i}',title=domain+' practice',text=text+'\n'+explanation,source=q['source'],repository='trained',language='en',tags=[subject,domain]))
chunks.append(dict(id='demo-predicates',title='Equivalent open propositions',text='Open propositions P(x) and Q(x) are equivalent over a universe U when P(a) and Q(a) have the same truth value for every a in U. Equivalence depends on the chosen universe. For U = {-1, 1}, x² = 1 and |x| = 1 are both true for every member.',source='Havan authored demonstration note — not an official module',repository='modules',language='en',tags=['logic','predicates','equivalent','open propositions','ሎጂክ']))
Path('data/demo.json').write_text(json.dumps(dict(schemaVersion=1,chunks=chunks,questions=qs),ensure_ascii=False,indent=2))
